					active: checkpoint.telemetry.registration.active,
					controlled: checkpoint.telemetry.controller !== null,
					caches: checkpoint.telemetry.cacheNames.length,
				})),
			},
			mockedSeamPolicy: {
				policy: seams?.policy,
