1100	 * The settled result of the settings-change, leg (d) — the last journey leg.
1101	 *
1102	 * Three measured parts, each a RULE rather than a pinned literal, because the
1103	 * one lane-divergent part (the theme rgb) is a declared difference and the rest
1104	 * is measured the same in both lanes:
1105	 *
1106	 *  - `projectSwitch`: the create grew the side-nav list by exactly one, and the
1107	 *    switch flipped the current-project title to the project the create named —
1108	 *    `currentTitleAfter` equals `newProjectTitle` and differs from
1109	 *    `currentTitleBefore`. The literal titles are measured and travel, because
1110	 *    they are the application's own and agree across lanes.
1111	 *  - `theme`: the driven `huePrimary` mat-select change shifted the measured
1112	 *    `styleVar` — `styleValueBefore` differs from `styleValueAfter`. The literal
1113	 *    rgb values are per-lane and may differ (the declared lane difference on
1114	 *    {@link WITNESS_ANGULAR_SUPER_PRODUCTIVITY_SETTINGS}); the parity digest
1115	 *    carries only the fact THAT the driven change shifted the var, not the value.
1116	 *  - `shortcut`: `w` brought the work view — its host tag rendered after the
1117	 *    press. The `b` non-claim is recorded on the settings constant.
1118	 */
1119	export type WitnessAngularSuperProductivitySettings = {
1120		state: 'measured-settings-change';
1121		projectSwitch: {
1122			control: string;
1123			dialog: string;
1124			titleControl: string;
1125			switchControl: string;
1126			newProjectTitle: string;
1127			currentTitleBefore: string;
1128			currentTitleAfter: string;
1129			projectCountBefore: number;
1130			projectCountAfter: number;
1131		};
1132		theme: {
1133			autoContrastControl: string;
1134			control: string;
1135			styleVar: string;
1136			styleValueBefore: string;
1137			styleValueAfter: string;
1138		};
1139		shortcut: {
1140			key: string;
1141			hostTag: string;
1142			hostTagPresentAfter: number;
1143		};
1144	};
1145	
1146	/**
1147	 * The application-specific journey evidence.
1148	 *
1149	 * `typeface` and `persistence` are the facts legs (a) and (e) measure and are
1150	 * always present. `drag` (leg b), `timeTracking` (leg c) and `settings` (leg d)
1151	 * are the legs this journey drives: the parser requires all three once a browser
1152	 * has driven the journey, but they are typed optional so a producer can populate
1153	 * them without the not-yet-updated wiring failing to compile.
1154	 */
1155	export type WitnessAngularSuperProductivityJourney = {
1156		typeface: WitnessAngularSuperProductivityTypeface;
1157		persistence: WitnessAngularSuperProductivityPersistenceEvidence;
1158		drag?: WitnessAngularSuperProductivityDrag;
1159		timeTracking?: WitnessAngularSuperProductivityTimeTracking;
1160		settings?: WitnessAngularSuperProductivitySettings;
1161	};
