1234	function tallyConsoleErrors(page: PageRecord, origin: string): WitnessConsoleErrorInventoryEntry[] {
1235		const counts = new Map<string, number>();
1236		for (const message of page.consoleMessages) {
1237			if (message.level !== 'error') continue;
1238			const normalized = message.text.split(origin).join(CONSOLE_ORIGIN_PLACEHOLDER);
1239			counts.set(normalized, (counts.get(normalized) ?? 0) + 1);
1240		}
