1249	 * the inventory is reported by its own text rather than folded into a total.
1250	 */
1251	function buildConsoleErrorInventory(
1252		page: PageRecord,
1253		origin: string,
1254		expected: readonly WitnessConsoleErrorInventoryEntry[],
1255	): WitnessConsoleErrorInventory {
1256		const observed = tallyConsoleErrors(page, origin);
1257		const pinned = expected
1258			.map((entry) => ({ message: entry.message, count: entry.count }))
1259			.sort((left, right) => compareUtf16CodeUnits(left.message, right.message));
1260		const pinnedMessages = new Set(pinned.map((entry) => entry.message));
1261		const outside = observed.filter((entry) => !pinnedMessages.has(entry.message));
